<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=1920,initial-scale=1">
    <title>{{ $competition->tournament->name }} · Transmisión</title>
    <style>
        :root{--navy:#07172b;--blue:#174789;--green:#00a86b;--gold:#f2b705;--line:#37506d;--white:#f7fbff;--muted:#9fb3ca}*{box-sizing:border-box}html,body{width:1920px;height:180px;margin:0;overflow:hidden;background:transparent;font-family:Inter,Arial,sans-serif;color:var(--white)}body{background:linear-gradient(100deg,#06101e 0%,#0b2039 55%,#07172b 100%)}#stage{position:relative;width:1920px;height:180px;border-top:4px solid var(--gold);border-bottom:4px solid var(--blue);overflow:hidden}.slide{display:grid;grid-template-columns:315px 1fr;height:172px;animation:enter .45s ease both}.identity{display:flex;flex-direction:column;justify-content:center;padding:14px 20px;background:linear-gradient(120deg,#173d7c,#0b294e);border-right:2px solid var(--gold)}.live{display:flex;align-items:center;gap:8px;color:#ffdc64;font-size:13px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.live:before{content:"";width:10px;height:10px;border-radius:50%;background:#ff3c4f;box-shadow:0 0 0 5px rgba(255,60,79,.18);animation:pulse 1.4s infinite}.tournament{margin-top:9px;font-size:24px;font-weight:1000;line-height:1.05;text-transform:uppercase}.counter{margin-top:9px;color:#b9cee5;font-size:12px}.content{display:grid;grid-template-rows:43px 1fr;padding:7px 14px 8px}.heading{display:flex;align-items:center;gap:14px;min-width:0}.phase{font-size:21px;font-weight:1000;text-transform:uppercase}.context{padding:5px 10px;border-radius:999px;background:#173d7c;color:#fff;font-size:13px;font-weight:900}.updated{margin-left:auto;color:var(--muted);font-size:12px}.zone-layout{display:grid;grid-template-columns:1.55fr .95fr;gap:12px;min-height:0}.matches{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.match{min-width:0;padding:6px 9px;border:1px solid var(--line);border-left:5px solid #71849a;border-radius:7px;background:rgba(14,36,62,.94)}.match.called{border-color:var(--gold);border-left-color:var(--gold);background:rgba(83,64,5,.92)}.match.in_progress{border-color:var(--green);border-left-color:var(--green);background:rgba(4,67,48,.94)}.match.completed{border-left-color:#3f8cff;background:rgba(18,51,90,.94)}.match-title{display:flex;justify-content:space-between;gap:8px;color:#8fb5e6;font-size:10px;font-weight:900;text-transform:uppercase}.table{color:#ffd957}.player{display:flex;justify-content:space-between;gap:7px;padding-top:3px;font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden}.player span:first-child{overflow:hidden;text-overflow:ellipsis}.player.winner{color:#5aeda7}.score{flex:none;font-size:13px}.standings{width:100%;border-collapse:collapse;background:rgba(7,22,40,.8);font-size:10px}.standings th{padding:4px;background:#07844d;color:#fff;text-transform:uppercase}.standings td{padding:4px 6px;border:1px solid #2d4561;text-align:center}.standings td:nth-child(2){max-width:180px;text-align:left;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bracket-layout{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px;align-items:center}.empty{display:grid;place-items:center;height:100%;color:var(--muted);font-size:18px}.progress{position:absolute;left:0;bottom:0;height:4px;background:var(--gold);animation:progress linear both}@keyframes enter{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}@keyframes pulse{50%{opacity:.45}}@keyframes progress{from{width:0}to{width:100%}}
    </style>
</head>
<body>
<main id="stage"><div class="empty">Cargando resultados en vivo…</div></main>
<script>
const endpoint=@json($jsonUrl),config=@json($broadcastConfig),stage=document.querySelector('#stage');
let data=null,slides=[],activeSlide=0,lastPayload='',loading=false,rotationTimer=null;
const esc=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const matchState=match=>['called','in_progress','completed'].includes(match.estado)?match.estado:'';
const score=(match,side)=>{if(match.estado!=='completed'&&match.estado!=='in_progress')return '—';const values=match.sets_computables||[];return esc(values[side]??'—')};
function identity(index){return '<aside class="identity"><div class="live">Resultados en vivo</div><div class="tournament">'+esc(data.torneo)+'</div><div class="counter">Pantalla '+(index+1)+' de '+slides.length+'</div></aside>'}
function matchCard(match){const winner=match.ganador||'';return '<article class="match '+matchState(match)+'"><div class="match-title"><span>'+esc(match.etiqueta||('Ronda '+match.ronda))+'</span>'+(match.mesa?'<span class="table">Mesa '+esc(match.mesa)+'</span>':'')+'</div><div class="player '+(winner===match.jugador_1?'winner':'')+'"><span>'+esc(match.jugador_1||'A definir')+'</span><b class="score">'+score(match,0)+'</b></div><div class="player '+(winner===match.jugador_2?'winner':'')+'"><span>'+esc(match.jugador_2||'A definir')+'</span><b class="score">'+score(match,1)+'</b></div></article>'}
function zoneSlide(phase,zone){const matches=phase.partidos.filter(match=>Number(match.zona_id)===Number(zone.id));const standings=zone.jugadores.slice().sort((a,b)=>(a.clasificacion||99)-(b.clasificacion||99));return {key:'zone-'+zone.id,html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+' · '+esc(zone.nombre)+'</div><div class="context">'+esc(zone.horario||'Sin horario')+'</div><div class="updated">Actualización automática</div></div><div class="zone-layout"><div class="matches">'+matches.map(matchCard).join('')+'</div><table class="standings"><thead><tr><th>Pos</th><th>Jugador</th><th>PG</th><th>DS</th><th>Prom</th></tr></thead><tbody>'+standings.map(row=>'<tr><td>'+esc(row.clasificacion)+'</td><td>'+esc(row.nombre)+'</td><td>'+esc(row.partidos_ganados)+'</td><td>'+esc(row.diferencia_sets)+'</td><td>'+esc(row.promedio)+'</td></tr>').join('')+'</tbody></table></div>'}}
function scheduleMatches(phase,schedule){return phase.partidos.filter(match=>{if(Number(match.ronda)!==Number(schedule.round_number))return false;const from=Number(schedule.from_match||0),to=Number(schedule.to_match||0);return (!from||Number(match.orden)>=from)&&(!to||Number(match.orden)<=to)})}
function bracketSlides(phase){const schedules=phase.horarios_fase?.length?phase.horarios_fase:[{name:'Todos los partidos'}],result=[];schedules.forEach((schedule,scheduleIndex)=>{const matches=phase.horarios_fase?.length?scheduleMatches(phase,schedule):phase.partidos;for(let offset=0;offset<matches.length;offset+=5){result.push({key:'phase-'+phase.id+'-'+scheduleIndex+'-'+offset,html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div><div class="context">'+esc(schedule.name||'Partidos')+'</div><div class="updated">Actualización automática</div></div><div class="bracket-layout">'+matches.slice(offset,offset+5).map(matchCard).join('')+'</div>'})}});return result}
function buildSlides(){const allowedPhases=(config.allPhases?data.fases:data.fases.filter(phase=>config.phaseIds.includes(Number(phase.id))));const allowedSlots=config.zoneSlotKeys||[];slides=allowedPhases.flatMap(phase=>phase.tipo==='zones'?phase.zonas.filter(zone=>!allowedSlots.length||allowedSlots.includes(zone.horario_clave)).map(zone=>zoneSlide(phase,zone)):bracketSlides(phase));if(activeSlide>=slides.length)activeSlide=0}
function showSlide(){if(!slides.length){stage.innerHTML='<div class="empty">No hay resultados configurados para la transmisión.</div>';return}const slide=slides[activeSlide];stage.innerHTML='<section class="slide">'+identity(activeSlide)+'<div class="content">'+slide.html+'</div></section><div class="progress" style="animation-duration:'+config.rotationSeconds+'s"></div>';clearTimeout(rotationTimer);rotationTimer=setTimeout(()=>{activeSlide=(activeSlide+1)%slides.length;showSlide()},config.rotationSeconds*1000)}
async function refresh(){if(loading)return;loading=true;try{const separator=endpoint.includes('?')?'&':'?',response=await fetch(endpoint+separator+'_='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw new Error('No fue posible obtener los resultados');const payload=await response.json(),signature=JSON.stringify(payload.data);if(signature!==lastPayload){const currentKey=slides[activeSlide]?.key;lastPayload=signature;data=payload.data;buildSlides();const sameIndex=slides.findIndex(slide=>slide.key===currentKey);if(sameIndex>=0)activeSlide=sameIndex;showSlide()}}catch(error){if(!data)stage.innerHTML='<div class="empty">'+esc(error.message)+'</div>'}finally{loading=false}}
refresh();setInterval(()=>{if(!document.hidden)refresh()},4000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
</script>
</body>
</html>
